@spec coordinator_spec  src=tests/specs/coordinator_spec.lua  loc=159  cases=6
@exercises coordinator (coord), commandManager (h.cmgr)
@surface   coord:register, coord:setActive, cmgr:invoke, cmgr:scope, coord:returnToArrange, coord:reloadAfterExternalMutation
@harness   mk

# Intent
  Pin-tests for the coordinator's page-routing surface: setActive scope-swap and returnToArrange.
  Render (frame/run) pulls in ImGui and is exercised manually in REAPER.

# Helpers
  @fn fakePage()  @ 21-31
      -- A page that records every bind / unbind so a test can read back what
      -- the coordinator did to it. revealTake is recorded too (returnToArrange).
  @fn lastCall(page)  @ 33-35
  @fn newCoord(h, registrations)  @ 38-48
      -- see docs/coordinator.md § Test wiring for newCoord

# Cases
  @case 'setActive swaps scope, unbinds the outgoing page, and binds the incoming tracker from the cursor'  [harness]  @ 52-64
  @case 'a page switch closes an open menu before it swaps the page scope'  [harness]  @ 71-86
  @case 'returnToArrange unbinds the tracker and rebinds arrange (no reveal)'  [harness]  @ 90-101
  @case 'returnToArrange is a no-op when the arrange page is not registered'  [harness]  @ 105-115
  @case 'reloadAfterExternalMutation resyncs the undo mirror before reloading the take'  [harness]  @ 121-136
  @case 'coordinator constructs the reaper bridge with an env exposing coord and the page() debug resolver'  [harness]  @ 140-157

# Uses (outbound edges)
  @use call coord:register  @ 44,149
  @use call coord:setActive  @ 59,79,96
  @use call cmgr:invoke  @ 78
  @use call cmgr:scope  @ 81,84
  @use call coord:returnToArrange  @ 97,112
  @use call coord:reloadAfterExternalMutation  @ 132

